import { z } from "zod";

export const Readiness = z.object({
  verdict: z.enum(["ready", "ask", "hand_back"]),
  reason: z.string(),
  kind: z.enum(["fe_bug", "be_bug", "add_tests", "small_feature", "dependency_bump", "docs", "other"]),
  size: z.enum(["small", "bigger", "fuzzy"]),
  how_to_check: z.string(),
  questions: z.array(z.string()).max(5),
  out_of_scope: z.array(z.enum(["migration", "auth", "grpc_contract", "infra"])),
});
export type Readiness = z.infer<typeof Readiness>;

export const readinessSchema = z.toJSONSchema(Readiness, { target: "draft-7" });

const r = await checkReadiness(h.key);
if (r.verdict === "hand_back") {
  await handBack(h.key, h.requester, r.reason);
  return "handed back";
}
if (r.verdict === "ask" || r.size !== "small") {
  await grill(h, run, r);
}
await setState(run, "Planning", "Writing the plan");
const vm = await claimSandbox("lite");

