import { readFileSync } from "node:fs";
import { Readiness } from "./readiness.js";

const tickets = JSON.parse(readFileSync("tickets.json", "utf8"));
const rows = tickets.map((t: { key: string; person: string; model: unknown }) => ({ ...t, model: Readiness.parse(t.model).verdict }));
const agree = rows.filter((t) => t.model === t.person).length / rows.length;
const falseReady = rows.filter((t) => t.model === "ready" && t.person !== "ready");
const go = falseReady.length === 0 && agree >= 0.8;
console.log(`${go ? "GO" : "NO-GO"}: agree ${Math.round(agree * 100)}%, false ready ${falseReady.length}${falseReady.map((t) => ` ${t.key}`).join("")}`);
